subroutine Power(base as integer, exponent as integer) as integer
    if exponent = 0 then
        return 1;
    else
        return base * Power(base, exponent - 1);
    endIf
endSubroutine

algorithm ComputePower
    define base as integer;
    define exponent as integer;
    read base;
    read exponent;
    write Power(base, exponent);
endAlgorithm
